export function getFixtureOrdersByStatus(status: string): WorkOsFixtureOrder[] {
  return WORK_OS_FIXTURE_ORDERS.filter((o) => o.status === status);
}

export function getFixtureOrder(id: string): WorkOsFixtureOrder | undefined {
  return WORK_OS_FIXTURE_ORDERS.find((o) => o.id === id);
}
